// Pose error metric example (illustrative)
function poseError(est, gt) {
  // est/gt: {R: rotation matrix, t: translation vector}
  const rotError = rotationDistance(est.R, gt.R);
  const transError = vectorDistance(est.t, gt.t);
  return { rotError, transError };
}
